targets.expr:
sum by (status) (
  increase(backend_api_db_queries_total{namespace="backend-api", job="backend-api", container="backend-api"}[$__rate_interval])
)

sum by (namespace, workload) (
  node_namespace_pod_container:container_cpu_usage_seconds_total:sum_irate{namespace!~"kube-system|flux-system|monitoring"}
  * on (namespace, pod) group_left (workload)
  namespace_workload_pod:kube_pod_owner:relabel
)

sum by (namespace, workload) (
  node_namespace_pod_container:container_cpu_usage_seconds_total:sum_irate{namespace!~"kube-system|flux-system|monitoring"}
  * on (namespace, pod) group_left (workload)
  namespace_workload_pod:kube_pod_owner:relabel
)
/
sum by (namespace, workload) (
  kube_pod_container_resource_requests{resource="cpu", namespace!~"kube-system|flux-system|monitoring"}
  * on (namespace, pod) group_left (workload)
  namespace_workload_pod:kube_pod_owner:relabel
)

sum by (namespace, workload) (
  container_memory_working_set_bytes{container!="", image!="", namespace!~"kube-system|flux-system|monitoring"}
  * on (namespace, pod) group_left (workload)
  namespace_workload_pod:kube_pod_owner:relabel
)

max by (namespace, workload) (
  sum by (namespace, pod, container) (
    container_memory_working_set_bytes{container!="", image!="", namespace!~"kube-system|flux-system|monitoring"}
  )
  / on (namespace, pod, container)
  kube_pod_container_resource_limits{resource="memory"}
  * on (namespace, pod) group_left (workload)
  namespace_workload_pod:kube_pod_owner:relabel
)

topk(10,
  sum by (namespace, pod) (
    container_memory_working_set_bytes{container!="", image!="", namespace!~"kube-system|flux-system|monitoring"}
  )
)

topk(10,
  sum by (namespace, pod) (
    node_namespace_pod_container:container_cpu_usage_seconds_total:sum_irate{namespace!~"kube-system|flux-system|monitoring"}
  )
)

topk(10,
  sum by (namespace, pod) (
    rate(container_cpu_cfs_throttled_periods_total{container!="", namespace!~"kube-system|flux-system|monitoring"}[$__rate_interval])
  )
  /
  sum by (namespace, pod) (
    rate(container_cpu_cfs_periods_total{container!="", namespace!~"kube-system|flux-system|monitoring"}[$__rate_interval])
  )
)

max by (state) (
  pg_stat_activity_max_tx_duration{namespace="postgres", datname="voize", state=~"active|idle in transaction"}
)
